From 1fded453693a848d87d2c27d245d4f03168b7e5a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 19 Nov 2026 15:19:58 +0100
Subject: [PATCH] kicker: Show a name for recent folders without a file name

Kickoff's History listed folders like smb:/ or smb://server/ without a
label, because their URL has no file name to show. Fall back to the
host name, or to the URL itself, as Dolphin does for its tab titles.

BUG: 516894
---
 applets/kicker/recentusagemodel.cpp | 5 ++++-
 1 file changed, 4 insertions(+), 1 deletion(-)

diff --git a/applets/kicker/recentusagemodel.cpp b/applets/kicker/recentusagemodel.cpp
index e28299e899..0b5ca55709 100644
--- a/applets/kicker/recentusagemodel.cpp
+++ b/applets/kicker/recentusagemodel.cpp
@@ -300,7 +300,10 @@ QVariant RecentUsageModel::docData(const QString &resource, int role, const QStr
         if (index.isValid()) {
             return m_placesModel->text(index);
         }
-        return fileItem.text();
+        if (const QString text = fileItem.text(); !text.isEmpty()) {
+            return text;
+        }
+        return url.host().isEmpty() ? url.toDisplayString(QUrl::PreferLocalFile) : url.host();
     } else if (role == Qt::DecorationRole) {
         auto fileItem = getFileItem();
         const auto index = findPlaceForKFileItem(fileItem);
